const PERIO_BANK = [{"id":1,"concept":"Anatomy & Tissues","stem":"Which structure forms the base of the gingival sulcus in health?","choices":["Free gingival groove","Junctional epithelium","Mucogingival junction","Alveolar mucosa"],"answer":1,"why":"The junctional epithelium attaches to the tooth and forms the epithelial base of the sulcus.","zh":"结合上皮附着于牙面并形成龈沟的上皮底部。","rationales":[{"en":"The free gingival groove may demarcate free from attached gingiva, but it does not form the sulcus base.","zh":"游离龈沟可分隔游离龈与附着龈，但不构成龈沟底。"},{"en":"Correct: the junctional epithelium forms the base of the sulcus and provides the epithelial attachment.","zh":"正确：结合上皮形成龈沟底并提供上皮附着。"},{"en":"The mucogingival junction separates attached gingiva from alveolar mucosa.","zh":"膜龈联合分隔附着龈与牙槽黏膜。"},{"en":"Alveolar mucosa is apical to the mucogingival junction and is not part of the sulcus.","zh":"牙槽黏膜位于膜龈联合根方，不属于龈沟。"}],"level":"Board-style","pearl":"The junctional epithelium attaches to the tooth and forms the epithelial base of the sulcus."},{"id":2,"concept":"Anatomy & Tissues","stem":"Which periodontal ligament fibre group primarily resists intrusive forces along the long axis of a tooth?","choices":["Horizontal fibres","Oblique fibres","Apical fibres","Interradicular fibres"],"answer":1,"why":"Oblique fibres are the largest PDL fibre group and resist vertical masticatory forces by converting them into tension on alveolar bone.","zh":"斜行纤维是牙周膜中最大的一组，可抵抗沿牙长轴的垂直咀嚼力。","rationales":[{"en":"Horizontal fibres mainly resist tipping and horizontal pressure.","zh":"水平纤维主要抵抗倾斜及水平压力。"},{"en":"Correct: oblique fibres are oriented to resist intrusive vertical forces.","zh":"正确：斜行纤维的方向使其能抵抗垂直压入力。"},{"en":"Apical fibres resist luxation and protect vessels and nerves at the apex.","zh":"根尖纤维主要抵抗脱位并保护根尖血管神经。"},{"en":"Interradicular fibres support multirooted teeth in the furcation area.","zh":"根间纤维位于多根牙分叉区并提供支持。"}],"level":"Board-style","pearl":"Oblique fibres are the largest PDL fibre group and resist vertical masticatory forces by converting them into tension on alveolar bone."},{"id":3,"concept":"Anatomy & Tissues","stem":"The alveolar crest is normally located approximately how far apical to the CEJ?","choices":["0–0.5 mm","1–2 mm","3–4 mm","5–6 mm"],"answer":1,"why":"In periodontal health, the alveolar crest is typically about 1–2 mm apical to the CEJ.","zh":"牙周健康时，牙槽嵴通常位于釉牙骨质界根方约1–2毫米。","rationales":[{"en":"A distance under 0.5 mm would be unusually close to the CEJ.","zh":"小于0.5毫米通常过于接近釉牙骨质界。"},{"en":"Correct: 1–2 mm is the normal radiographic relationship.","zh":"正确：1–2毫米是正常的影像学关系。"},{"en":"Three to four millimetres suggests crestal bone loss rather than health.","zh":"3–4毫米提示牙槽嵴骨丧失而非健康。"},{"en":"Five to six millimetres represents substantial bone loss.","zh":"5–6毫米代表明显骨丧失。"}],"level":"Clinical","pearl":"In periodontal health, the alveolar crest is typically about 1–2 mm apical to the CEJ."},{"id":4,"concept":"Assessment","stem":"Which finding is the earliest and most reliable clinical sign of gingival inflammation?","choices":["Tooth mobility","Bleeding on gentle probing","Radiographic bone loss","Suppuration"],"answer":1,"why":"Bleeding on gentle probing reflects ulceration and inflammation of the sulcular epithelium and often appears before visible colour change.","zh":"轻柔探诊出血反映龈沟上皮炎症和溃疡，常早于明显颜色改变。","rationales":[{"en":"Mobility is a later finding related to attachment or bone loss, trauma, or inflammation.","zh":"松动通常是附着或骨丧失、创伤或炎症的较晚表现。"},{"en":"Correct: bleeding on probing is a sensitive early sign of gingival inflammation.","zh":"正确：探诊出血是牙龈炎症敏感的早期征象。"},{"en":"Radiographic bone loss indicates periodontitis, not the earliest gingivitis sign.","zh":"影像学骨丧失提示牙周炎，并非牙龈炎最早征象。"},{"en":"Suppuration indicates more advanced infection and is not an early finding.","zh":"溢脓提示更进展的感染，并非早期表现。"}],"level":"Board-style","pearl":"Bleeding on gentle probing reflects ulceration and inflammation of the sulcular epithelium and often appears before visible colour change."},{"id":5,"concept":"Assessment","stem":"A probing depth is measured from the:","choices":["CEJ to the base of the pocket","Gingival margin to the base of the sulcus or pocket","CEJ to the gingival margin","Alveolar crest to the gingival margin"],"answer":1,"why":"Probing depth is the distance from the gingival margin to the base of the sulcus or periodontal pocket.","zh":"探诊深度是从龈缘到龈沟或牙周袋底的距离。","rationales":[{"en":"CEJ to pocket base is clinical attachment level, not probing depth.","zh":"从釉牙骨质界到袋底是临床附着水平，不是探诊深度。"},{"en":"Correct: the gingival margin is the coronal reference point for probing depth.","zh":"正确：龈缘是探诊深度的冠方参考点。"},{"en":"CEJ to gingival margin measures recession or gingival enlargement.","zh":"釉牙骨质界到龈缘测量的是龈退缩或增生。"},{"en":"The alveolar crest is not used as the clinical reference for probing depth.","zh":"牙槽嵴不作为探诊深度的临床参考点。"}],"level":"Board-style","pearl":"Probing depth is the distance from the gingival margin to the base of the sulcus or periodontal pocket."},{"id":6,"concept":"Assessment","stem":"A tooth has a 6 mm probing depth and 2 mm of gingival recession. What is the clinical attachment loss?","choices":["4 mm","6 mm","8 mm","12 mm"],"answer":2,"why":"When recession is present, CAL equals probing depth plus recession: 6 + 2 = 8 mm.","zh":"存在龈退缩时，临床附着丧失等于探诊深度加退缩：6 + 2 = 8毫米。","rationales":[{"en":"Four millimetres results from subtracting recession, which is incorrect when the margin is apical to the CEJ.","zh":"4毫米是错误地相减；龈缘位于釉牙骨质界根方时应相加。"},{"en":"Six millimetres ignores the additional attachment loss represented by recession.","zh":"6毫米忽略了龈退缩所代表的额外附着丧失。"},{"en":"Correct: 6 mm probing depth plus 2 mm recession equals 8 mm CAL.","zh":"正确：6毫米探诊深度加2毫米退缩等于8毫米附着丧失。"},{"en":"Twelve millimetres doubles the probing depth and has no clinical basis.","zh":"12毫米是将探诊深度加倍，没有临床依据。"}],"level":"Clinical","pearl":"When recession is present, CAL equals probing depth plus recession: 6 + 2 = 8 mm."},{"id":7,"concept":"Assessment","stem":"Class II furcation involvement is best described as:","choices":["Incipient horizontal loss less than 3 mm","A cul-de-sac defect with partial horizontal penetration","A through-and-through defect covered by soft tissue","A clinically visible through-and-through defect"],"answer":1,"why":"Class II furcation involvement is a partial horizontal, cul-de-sac defect that does not pass completely through the furcation.","zh":"II度分叉病变为部分水平进入的盲袋状缺损，尚未完全贯通。","rationales":[{"en":"Incipient involvement is Class I.","zh":"初期、少于约3毫米的分叉受累属于I度。"},{"en":"Correct: Class II permits partial penetration but is not through-and-through.","zh":"正确：II度可部分进入，但未完全贯通。"},{"en":"A covered through-and-through defect is Class III.","zh":"被软组织覆盖的完全贯通缺损属于III度。"},{"en":"A clinically visible through-and-through defect is Class IV.","zh":"临床可见的完全贯通缺损属于IV度。"}],"level":"Board-style","pearl":"Class II furcation involvement is a partial horizontal, cul-de-sac defect that does not pass completely through the furcation."},{"id":8,"concept":"Assessment","stem":"Which mobility classification indicates horizontal movement greater than 1 mm without vertical depressibility?","choices":["Class I","Class II","Class III","Physiologic mobility"],"answer":1,"why":"Class II mobility is horizontal movement greater than 1 mm without vertical movement.","zh":"II度松动指水平移动超过1毫米但无垂直向压入。","rationales":[{"en":"Class I is horizontal mobility up to about 1 mm.","zh":"I度松动为水平移动约不超过1毫米。"},{"en":"Correct: Class II exceeds 1 mm horizontally without vertical displacement.","zh":"正确：II度为水平超过1毫米且无垂直位移。"},{"en":"Class III includes vertical depressibility in addition to severe horizontal mobility.","zh":"III度除严重水平松动外还包括垂直向压入。"},{"en":"Physiologic mobility is slight normal movement and is not classified as greater than 1 mm.","zh":"生理性松动是轻微正常移动，不会超过1毫米。"}],"level":"Board-style","pearl":"Class II mobility is horizontal movement greater than 1 mm without vertical movement."},{"id":9,"concept":"Gingivitis","stem":"Plaque-induced gingivitis is characterized by:","choices":["Attachment loss and radiographic bone loss","Inflammation confined to the gingiva without attachment loss","Necrosis of interdental papillae in all cases","Irreversible destruction of the periodontium"],"answer":1,"why":"Plaque-induced gingivitis causes reversible gingival inflammation without clinical attachment or bone loss.","zh":"菌斑诱导性牙龈炎为可逆性牙龈炎症，不伴临床附着或骨丧失。","rationales":[{"en":"Attachment and bone loss define periodontitis, not simple gingivitis.","zh":"附着和骨丧失定义的是牙周炎，而非单纯牙龈炎。"},{"en":"Correct: inflammation is limited to gingival tissues and is reversible with biofilm control.","zh":"正确：炎症局限于牙龈组织，控制菌斑后可逆。"},{"en":"Papillary necrosis is characteristic of necrotizing periodontal disease, not routine gingivitis.","zh":"牙间乳头坏死是坏死性牙周病特征，不是一般牙龈炎。"},{"en":"Gingivitis is reversible and does not involve irreversible periodontal destruction.","zh":"牙龈炎可逆，不涉及不可逆的牙周组织破坏。"}],"level":"Clinical","pearl":"Plaque-induced gingivitis causes reversible gingival inflammation without clinical attachment or bone loss."},{"id":10,"concept":"Gingivitis","stem":"Pregnancy-associated gingivitis is primarily related to:","choices":["Direct bacterial invasion caused by the fetus","An exaggerated inflammatory response to plaque influenced by hormonal changes","Permanent attachment loss in every patient","Vitamin C toxicity"],"answer":1,"why":"Pregnancy hormones modify the gingival inflammatory response, producing an exaggerated reaction to existing plaque.","zh":"妊娠激素会改变牙龈炎症反应，使现有菌斑引起更强烈的炎症。","rationales":[{"en":"The fetus does not directly cause bacterial invasion of gingiva.","zh":"胎儿不会直接造成牙龈细菌侵入。"},{"en":"Correct: hormonal changes amplify the tissue response to plaque.","zh":"正确：激素变化会放大牙龈对菌斑的反应。"},{"en":"Pregnancy gingivitis does not inevitably cause attachment loss.","zh":"妊娠性牙龈炎并不必然导致附着丧失。"},{"en":"Vitamin C toxicity is not the mechanism of pregnancy gingivitis.","zh":"维生素C中毒不是妊娠性牙龈炎的机制。"}],"level":"Board-style","pearl":"Pregnancy hormones modify the gingival inflammatory response, producing an exaggerated reaction to existing plaque."},{"id":11,"concept":"Periodontitis","stem":"The defining feature that distinguishes periodontitis from gingivitis is:","choices":["Bleeding on probing","Clinical attachment loss due to periodontal destruction","Plaque accumulation","Gingival redness"],"answer":1,"why":"Periodontitis is defined by irreversible loss of periodontal attachment, often with alveolar bone loss.","zh":"牙周炎的定义特征是不可逆的牙周附着丧失，常伴牙槽骨丧失。","rationales":[{"en":"Bleeding can occur in gingivitis and does not by itself establish periodontitis.","zh":"探诊出血也可见于牙龈炎，不能单独确诊牙周炎。"},{"en":"Correct: attachment loss indicates destruction of the supporting periodontium.","zh":"正确：附着丧失表示支持性牙周组织已被破坏。"},{"en":"Plaque is an etiologic factor but does not distinguish the two conditions.","zh":"菌斑是病因因素，但不能区分两者。"},{"en":"Redness is a nonspecific sign of inflammation and may occur in gingivitis.","zh":"发红是非特异性炎症征象，牙龈炎也可出现。"}],"level":"Board-style","pearl":"Periodontitis is defined by irreversible loss of periodontal attachment, often with alveolar bone loss."},{"id":12,"concept":"Periodontitis","stem":"In the 2018 classification, staging of periodontitis primarily reflects:","choices":["Only the patient’s age","Severity, complexity, and extent of disease","Only plaque score","Only smoking status"],"answer":1,"why":"Stage describes current severity, complexity of management, and extent/distribution.","zh":"分期描述当前疾病严重度、治疗复杂性及范围/分布。","rationales":[{"en":"Age may influence interpretation but does not by itself determine stage.","zh":"年龄可影响判断，但不能单独决定分期。"},{"en":"Correct: staging integrates severity, complexity, and extent.","zh":"正确：分期综合严重度、复杂性和范围。"},{"en":"Plaque score is important clinically but is not the sole staging criterion.","zh":"菌斑评分重要，但不是唯一分期标准。"},{"en":"Smoking modifies grade rather than directly determining stage.","zh":"吸烟主要影响分级，而不是直接决定分期。"}],"level":"Clinical","pearl":"Stage describes current severity, complexity of management, and extent/distribution."},{"id":13,"concept":"Periodontitis","stem":"Grading periodontitis is intended to estimate:","choices":["Tooth colour","Rate of progression and future risk","Pocket depth only","Amount of calculus only"],"answer":1,"why":"Grade estimates the rate of progression, anticipated response, and impact of risk factors such as smoking and diabetes.","zh":"分级用于估计进展速度、预期治疗反应及吸烟和糖尿病等危险因素的影响。","rationales":[{"en":"Tooth colour is unrelated to periodontal grade.","zh":"牙齿颜色与牙周分级无关。"},{"en":"Correct: grade reflects progression and risk profile.","zh":"正确：分级反映疾病进展和风险特征。"},{"en":"Pocket depth contributes to assessment but does not alone determine grade.","zh":"袋深参与评估，但不能单独决定分级。"},{"en":"Calculus amount is not the basis of grading.","zh":"牙石量不是分级依据。"}],"level":"Board-style","pearl":"Grade estimates the rate of progression, anticipated response, and impact of risk factors such as smoking and diabetes."},{"id":14,"concept":"Periodontitis","stem":"A patient with severe attachment loss at a young age and rapid documented progression is most consistent with:","choices":["Grade A","Grade B","Grade C","Gingivitis only"],"answer":2,"why":"Grade C indicates rapid progression or a high disease burden relative to age.","zh":"C级表示快速进展，或相对于年龄疾病负担异常高。","rationales":[{"en":"Grade A represents slow progression.","zh":"A级代表缓慢进展。"},{"en":"Grade B represents moderate expected progression.","zh":"B级代表中等、预期的进展速度。"},{"en":"Correct: rapid progression in a young patient supports Grade C.","zh":"正确：年轻患者快速进展支持C级。"},{"en":"Severe attachment loss excludes a diagnosis of gingivitis alone.","zh":"严重附着丧失排除单纯牙龈炎。"}],"level":"Board-style","pearl":"Grade C indicates rapid progression or a high disease burden relative to age."},{"id":15,"concept":"Risk Factors","stem":"Which factor is considered a major modifiable risk factor for periodontitis progression?","choices":["Smoking","Eye colour","Left-handedness","Blood type"],"answer":0,"why":"Smoking strongly increases periodontal disease severity, progression, and impaired healing.","zh":"吸烟会显著增加牙周病严重度和进展，并损害愈合。","rationales":[{"en":"Correct: smoking is a major modifiable periodontal risk factor.","zh":"正确：吸烟是重要且可改变的牙周危险因素。"},{"en":"Eye colour has no established causal relationship with periodontitis.","zh":"眼睛颜色与牙周炎没有已知因果关系。"},{"en":"Handedness is not a recognized major risk factor.","zh":"惯用手不是公认的主要危险因素。"},{"en":"Blood type does not guide routine periodontal risk assessment.","zh":"血型不用于常规牙周风险评估。"}],"level":"Clinical","pearl":"Smoking strongly increases periodontal disease severity, progression, and impaired healing."},{"id":16,"concept":"Risk Factors","stem":"Poorly controlled diabetes increases periodontal risk primarily because it:","choices":["Improves neutrophil function","Promotes dysregulated inflammation and impaired wound healing","Eliminates subgingival biofilm","Prevents collagen breakdown"],"answer":1,"why":"Hyperglycemia promotes an exaggerated inflammatory response, altered host defence, microvascular change, and impaired repair.","zh":"高血糖会造成炎症反应失调、宿主防御改变、微血管变化及修复受损。","rationales":[{"en":"Diabetes can impair rather than improve neutrophil function.","zh":"糖尿病会损害而非改善中性粒细胞功能。"},{"en":"Correct: dysregulated inflammation and impaired healing increase periodontal destruction.","zh":"正确：炎症失调和愈合受损会增加牙周破坏。"},{"en":"Diabetes does not eliminate subgingival biofilm.","zh":"糖尿病不会消除龈下菌斑。"},{"en":"Diabetes may enhance collagen breakdown rather than prevent it.","zh":"糖尿病可能增强而非防止胶原降解。"}],"level":"Board-style","pearl":"Hyperglycemia promotes an exaggerated inflammatory response, altered host defence, microvascular change, and impaired repair."},{"id":17,"concept":"Bone Loss","stem":"Radiographic bone loss that remains approximately parallel to a line connecting adjacent CEJs is classified as:","choices":["Horizontal bone loss","Vertical bone loss","Furcation involvement","Fenestration"],"answer":0,"why":"Horizontal bone loss reduces bone height while the crest remains roughly parallel to the CEJ line.","zh":"水平型骨丧失表现为骨高度降低，但牙槽嵴仍大致平行于相邻釉牙骨质界连线。","rationales":[{"en":"Correct: the parallel crestal pattern defines horizontal bone loss.","zh":"正确：牙槽嵴平行下降定义水平型骨丧失。"},{"en":"Vertical bone loss creates an angular defect not parallel to the CEJ line.","zh":"垂直型骨丧失形成不平行于釉牙骨质界连线的角形缺损。"},{"en":"Furcation involvement refers specifically to bone loss between roots.","zh":"分叉受累特指牙根之间的骨丧失。"},{"en":"Fenestration is an isolated window of missing cortical bone over a root.","zh":"骨开窗是牙根表面局部皮质骨缺失窗口。"}],"level":"Board-style","pearl":"Horizontal bone loss reduces bone height while the crest remains roughly parallel to the CEJ line."},{"id":18,"concept":"Bone Loss","stem":"A three-wall intrabony defect generally has:","choices":["The least remaining bony support and poorest regenerative potential","Three remaining osseous walls and favourable regenerative potential","No relationship to periodontal therapy","Only soft-tissue involvement"],"answer":1,"why":"Three-wall defects retain more vascular bony walls and are generally the most favourable intrabony defects for regeneration.","zh":"三壁骨内缺损保留较多有血供的骨壁，通常最有利于再生治疗。","rationales":[{"en":"One-wall defects have less remaining support and poorer regenerative containment.","zh":"一壁缺损剩余支持较少，再生条件较差。"},{"en":"Correct: three remaining walls provide blood supply and containment.","zh":"正确：三面残存骨壁提供血供和良好空间维持。"},{"en":"Defect morphology directly influences treatment planning and regenerative potential.","zh":"缺损形态会直接影响治疗计划和再生潜力。"},{"en":"An intrabony defect is a hard-tissue osseous defect, not only a soft-tissue change.","zh":"骨内缺损属于硬组织骨缺损，并非仅为软组织改变。"}],"level":"Clinical","pearl":"Three-wall defects retain more vascular bony walls and are generally the most favourable intrabony defects for regeneration."},{"id":19,"concept":"Instrumentation","stem":"The primary purpose of periodontal debridement is to:","choices":["Remove all cementum from every root","Disrupt and remove pathogenic biofilm and calculus while preserving tooth structure","Create a glass-smooth root at any cost","Remove healthy gingiva"],"answer":1,"why":"Modern debridement aims to remove biofilm and calculus sufficiently for tissue health while avoiding unnecessary root damage.","zh":"现代牙周清创旨在充分去除菌斑和牙石、恢复组织健康，同时避免不必要的根面损伤。","rationales":[{"en":"Aggressive removal of all cementum is unnecessary and can cause sensitivity.","zh":"过度去除全部牙骨质没有必要，并可导致敏感。"},{"en":"Correct: effective biofilm and calculus disruption with tissue preservation is the goal.","zh":"正确：目标是有效破坏菌斑和牙石并保护牙体组织。"},{"en":"A perfectly glass-smooth root is not required and may sacrifice excessive tooth structure.","zh":"不必追求完全玻璃样光滑，否则可能过度损伤牙体。"},{"en":"Healthy gingiva should be preserved, not removed.","zh":"健康牙龈应予保留，而不是去除。"}],"level":"Board-style","pearl":"Modern debridement aims to remove biofilm and calculus sufficiently for tissue health while avoiding unnecessary root damage."},{"id":20,"concept":"Instrumentation","stem":"Which instrument is best suited for detecting residual subgingival calculus after debridement?","choices":["Explorer with a fine flexible tip","Periodontal file only","Cotton pliers","Amalgam condenser"],"answer":0,"why":"A fine explorer is designed to detect subtle root surface irregularities and residual calculus.","zh":"细而灵活的探针适于检测根面细微不规则及残余龈下牙石。","rationales":[{"en":"Correct: a fine explorer provides tactile sensitivity for residual deposits.","zh":"正确：细探针具良好触觉敏感性，可检测残余沉积物。"},{"en":"A periodontal file crushes heavy deposits but is less sensitive for final detection.","zh":"牙周锉可压碎厚重牙石，但不适合最终精细检查。"},{"en":"Cotton pliers are used to carry materials, not explore root surfaces.","zh":"棉镊用于夹取材料，不用于探查根面。"},{"en":"An amalgam condenser is a restorative instrument and cannot assess subgingival calculus.","zh":"银汞充填器是修复器械，不能评估龈下牙石。"}],"level":"Board-style","pearl":"A fine explorer is designed to detect subtle root surface irregularities and residual calculus."},{"id":21,"concept":"Instrumentation","stem":"When adapting a Gracey curette, the terminal shank should be:","choices":["Perpendicular to the tooth surface being instrumented","Parallel to the tooth surface being instrumented","Pointed away from the tooth","Horizontal to the occlusal plane in every area"],"answer":1,"why":"Correct Gracey adaptation is achieved when the lower terminal shank is parallel to the tooth surface.","zh":"Gracey刮治器正确适应时，下部末端柄应与所操作牙面平行。","rationales":[{"en":"A perpendicular terminal shank produces incorrect blade angulation.","zh":"末端柄垂直会造成错误的刃角。"},{"en":"Correct: parallel alignment identifies the correct working end and angulation.","zh":"正确：平行关系有助于确认正确工作端和刃角。"},{"en":"Pointing away from the tooth does not describe proper adaptation.","zh":"指向远离牙面不能代表正确适应。"},{"en":"The terminal shank orientation changes with tooth surface and is not always horizontal to the occlusal plane.","zh":"末端柄方向随牙面而变，并非始终与咬合面水平。"}],"level":"Clinical","pearl":"Correct Gracey adaptation is achieved when the lower terminal shank is parallel to the tooth surface."},{"id":22,"concept":"Instrumentation","stem":"The ideal working angulation for calculus removal with a curette is approximately:","choices":["0–10°","20–30°","60–80°","90–110°"],"answer":2,"why":"A curette is generally opened to about 60–80° between the face and tooth surface for calculus removal.","zh":"使用刮治器去除牙石时，器械面与牙面通常形成约60–80°工作角。","rationales":[{"en":"Zero to ten degrees is a closed insertion angle, not an effective removal angle.","zh":"0–10°是闭合插入角，不是有效去石角。"},{"en":"Twenty to thirty degrees is too closed for effective calculus removal.","zh":"20–30°过于闭合，难以有效去除牙石。"},{"en":"Correct: 60–80° provides an effective cutting edge while limiting tissue trauma.","zh":"正确：60–80°可有效使用刃口并限制组织损伤。"},{"en":"Angles over 90° risk tissue trauma and poor blade adaptation.","zh":"超过90°容易造成组织创伤和刃口适应不良。"}],"level":"Board-style","pearl":"A curette is generally opened to about 60–80° between the face and tooth surface for calculus removal."},{"id":23,"concept":"Treatment","stem":"Following initial nonsurgical periodontal therapy, reevaluation is commonly scheduled after approximately:","choices":["24 hours","1 week","4–6 weeks","1 year"],"answer":2,"why":"Four to six weeks allows sufficient soft-tissue healing and maturation for meaningful reassessment.","zh":"4–6周可让软组织充分愈合和成熟，便于有意义的再评估。","rationales":[{"en":"Twenty-four hours is too soon to assess the full tissue response.","zh":"24小时过早，无法评估完整组织反应。"},{"en":"One week may assess acute healing but is usually too early for definitive reevaluation.","zh":"1周可观察早期愈合，但通常过早进行正式再评估。"},{"en":"Correct: 4–6 weeks is a common interval for periodontal reevaluation.","zh":"正确：4–6周是常用牙周再评估时间。"},{"en":"Waiting a year would delay necessary additional therapy and maintenance planning.","zh":"等待一年会延误进一步治疗和维护计划。"}],"level":"Board-style","pearl":"Four to six weeks allows sufficient soft-tissue healing and maturation for meaningful reassessment."},{"id":24,"concept":"Treatment","stem":"Which finding at reevaluation most strongly supports referral for possible periodontal surgery?","choices":["Resolved inflammation and shallow pockets","Persistent deep pockets with bleeding and inaccessible deposits","Excellent plaque control with no bleeding","Physiologic mobility only"],"answer":1,"why":"Persistent deep bleeding pockets after adequate nonsurgical therapy may require surgical access or regenerative treatment.","zh":"充分非手术治疗后仍存在深袋、出血及难以清除的沉积物，可能需要手术进入或再生治疗。","rationales":[{"en":"Resolved inflammation and shallow pockets indicate successful nonsurgical care.","zh":"炎症消退且袋浅表示非手术治疗成功。"},{"en":"Correct: persistent inaccessible disease is a key indication for specialist or surgical consideration.","zh":"正确：持续且难以接近的病变是考虑专科或手术治疗的重要指征。"},{"en":"Excellent plaque control without bleeding does not support surgery.","zh":"菌斑控制良好且无出血不支持手术。"},{"en":"Physiologic mobility is normal and does not require periodontal surgery.","zh":"生理性松动属正常，不需牙周手术。"}],"level":"Clinical","pearl":"Persistent deep bleeding pockets after adequate nonsurgical therapy may require surgical access or regenerative treatment."},{"id":25,"concept":"Maintenance","stem":"The periodontal maintenance interval should be determined primarily by:","choices":["A fixed six-month schedule for every patient","Individual risk, disease severity, response to therapy, and self-care","The patient’s favourite season","Insurance limits alone"],"answer":1,"why":"Maintenance frequency is individualized according to recurrence risk and clinical response; many high-risk patients require about 3-month intervals.","zh":"维护间隔应根据复发风险和临床反应个体化；许多高风险患者约需每3个月维护。","rationales":[{"en":"A universal six-month interval may be inadequate for high-risk periodontal patients.","zh":"统一每6个月一次对高风险牙周患者可能不足。"},{"en":"Correct: individualized risk and response determine recall frequency.","zh":"正确：维护频率取决于个体风险和治疗反应。"},{"en":"Seasonal preference has no clinical role in maintenance planning.","zh":"季节偏好与维护计划无临床关系。"},{"en":"Insurance coverage should not replace professional clinical judgment.","zh":"保险限制不能取代专业临床判断。"}],"level":"Board-style","pearl":"Maintenance frequency is individualized according to recurrence risk and clinical response; many high-risk patients require about 3-month intervals."},{"id":26,"concept":"Maintenance","stem":"During periodontal maintenance, the clinician should:","choices":["Repeat a comprehensive assessment, reinforce self-care, and debride indicated sites","Scale every root surface aggressively regardless of findings","Avoid reviewing medical history","Ignore bleeding sites if the patient has no pain"],"answer":0,"why":"Periodontal maintenance includes reassessment, risk review, tailored instrumentation, and reinforcement of daily biofilm control.","zh":"牙周维护包括重新评估、风险复查、针对性器械清创及强化日常菌斑控制。","rationales":[{"en":"Correct: maintenance is active reassessment and individualized supportive therapy.","zh":"正确：维护是积极再评估和个体化支持治疗。"},{"en":"Unnecessary aggressive scaling can damage root surfaces and is not site-specific care.","zh":"不必要的强力刮治会损伤根面，也不符合针对性护理。"},{"en":"Medical history must be updated because systemic status and medications can change risk.","zh":"必须更新病史，因为全身状况和药物会改变风险。"},{"en":"Bleeding indicates inflammation and must be evaluated even without pain.","zh":"出血提示炎症，即使无痛也必须评估。"}],"level":"Board-style","pearl":"Periodontal maintenance includes reassessment, risk review, tailored instrumentation, and reinforcement of daily biofilm control."},{"id":27,"concept":"Necrotizing Disease","stem":"Necrotizing gingivitis is classically associated with:","choices":["Punched-out interdental papillae, pain, bleeding, and fetid odour","Generalized painless fibrotic enlargement only","Isolated tooth whitening","Asymptomatic bony exostoses"],"answer":0,"why":"Necrotizing gingivitis presents acutely with painful papillary necrosis, spontaneous bleeding, pseudomembrane, and malodour.","zh":"坏死性牙龈炎急性表现为牙间乳头坏死、疼痛、自发出血、假膜及口臭。","rationales":[{"en":"Correct: punched-out necrotic papillae and pain are hallmark findings.","zh":"正确：凿坑样坏死乳头和疼痛是典型表现。"},{"en":"Painless fibrotic enlargement is more consistent with chronic gingival overgrowth.","zh":"无痛纤维性增生更符合慢性牙龈增生。"},{"en":"Tooth whitening is unrelated to necrotizing periodontal disease.","zh":"牙齿美白与坏死性牙周病无关。"},{"en":"Bony exostoses are benign hard-tissue findings, not acute infection.","zh":"骨性外生骨疣是良性硬组织表现，不是急性感染。"}],"level":"Clinical","pearl":"Necrotizing gingivitis presents acutely with painful papillary necrosis, spontaneous bleeding, pseudomembrane, and malodour."},{"id":28,"concept":"Necrotizing Disease","stem":"The initial management of necrotizing periodontal disease should emphasize:","choices":["Gentle debridement, antimicrobial rinses as indicated, pain control, and risk-factor management","Immediate aggressive full-mouth surgery","No treatment because it is self-limiting","Extraction of all affected teeth"],"answer":0,"why":"Initial care focuses on gentle removal of necrotic debris and biofilm, symptom control, and correction of contributing factors.","zh":"初期处理重点是轻柔清除坏死组织和菌斑、控制症状并纠正相关危险因素。","rationales":[{"en":"Correct: gentle acute-phase care reduces pain and microbial load safely.","zh":"正确：轻柔的急性期处理可安全降低疼痛和微生物负荷。"},{"en":"Aggressive surgery during the acute painful phase is inappropriate.","zh":"在急性疼痛期立即进行强力全口手术不合适。"},{"en":"Untreated disease may progress and is not reliably self-limiting.","zh":"不治疗可能继续进展，并非可靠自限。"},{"en":"Extraction is not routinely indicated when teeth are maintainable.","zh":"牙齿可保留时不应常规全部拔除。"}],"level":"Board-style","pearl":"Initial care focuses on gentle removal of necrotic debris and biofilm, symptom control, and correction of contributing factors."},{"id":29,"concept":"Abscesses","stem":"A periodontal abscess most often presents as:","choices":["Localized painful swelling adjacent to a periodontal pocket, often with suppuration","A flat painless macule","Generalized enamel hypoplasia","A bony torus"],"answer":0,"why":"A periodontal abscess is an acute localized purulent infection within periodontal tissues, commonly associated with a deep pocket.","zh":"牙周脓肿是牙周组织内急性局限性化脓感染，常与深牙周袋有关。","rationales":[{"en":"Correct: localized pain, swelling, deep pocketing, and pus are typical.","zh":"正确：局限疼痛、肿胀、深袋和溢脓为典型表现。"},{"en":"A macule is a flat colour change and does not describe an abscess.","zh":"斑疹是平坦颜色改变，不能描述脓肿。"},{"en":"Enamel hypoplasia is a developmental tooth defect, not an acute periodontal infection.","zh":"釉质发育不全是牙体发育缺陷，不是急性牙周感染。"},{"en":"A torus is a benign bony growth and is not purulent or painful.","zh":"骨隆突是良性骨性增生，不会化脓或急性疼痛。"}],"level":"Board-style","pearl":"A periodontal abscess is an acute localized purulent infection within periodontal tissues, commonly associated with a deep pocket."},{"id":30,"concept":"Abscesses","stem":"A periodontal abscess differs from a periapical abscess because the periodontal abscess commonly has:","choices":["A vital pulp and a pre-existing periodontal pocket","A nonvital pulp in every case","No swelling or pain","No relationship to periodontal tissues"],"answer":0,"why":"Periodontal abscesses often arise from pocket obstruction around a tooth with a vital pulp, whereas periapical abscesses usually follow pulpal necrosis.","zh":"牙周脓肿常由牙周袋阻塞引起，牙髓可有活力；根尖脓肿通常继发于牙髓坏死。","rationales":[{"en":"Correct: pulp vitality and pocket findings help distinguish a periodontal source.","zh":"正确：牙髓活力和牙周袋表现有助于判断牙周来源。"},{"en":"A nonvital pulp is more characteristic of a periapical abscess.","zh":"无活力牙髓更符合根尖脓肿。"},{"en":"Both conditions may be painful and swollen.","zh":"两种情况都可能疼痛和肿胀。"},{"en":"A periodontal abscess by definition involves periodontal tissues.","zh":"牙周脓肿按定义即涉及牙周组织。"}],"level":"Clinical","pearl":"Periodontal abscesses often arise from pocket obstruction around a tooth with a vital pulp, whereas periapical abscesses usually follow pulpal necrosis."},{"id":31,"concept":"Mucogingival","stem":"Gingival recession is measured from the:","choices":["Gingival margin to the CEJ","Pocket base to alveolar crest","Incisal edge to CEJ","Mucogingival junction to pocket base"],"answer":0,"why":"Recession is the distance from the CEJ to an apically displaced gingival margin.","zh":"龈退缩是从釉牙骨质界到向根方移位的龈缘的距离。","rationales":[{"en":"Correct: the CEJ is the fixed reference point for recession.","zh":"正确：釉牙骨质界是测量龈退缩的固定参考点。"},{"en":"Pocket base to crest is not the clinical recession measurement.","zh":"袋底到牙槽嵴不是临床龈退缩测量。"},{"en":"Incisal edge to CEJ measures crown anatomy, not recession.","zh":"切缘到釉牙骨质界反映牙冠解剖，不是龈退缩。"},{"en":"The mucogingival junction is used to assess attached gingiva, not recession directly.","zh":"膜龈联合用于评估附着龈宽度，不直接测量退缩。"}],"level":"Board-style","pearl":"Recession is the distance from the CEJ to an apically displaced gingival margin."},{"id":32,"concept":"Mucogingival","stem":"A dehiscence is best described as:","choices":["An isolated window of bone loss with intact marginal bone","Loss of cortical bone extending through the alveolar margin along a root","A through-and-through furcation defect","A suprabony pocket"],"answer":1,"why":"Dehiscence is a denuded root area where cortical bone loss extends to and includes the alveolar crest.","zh":"骨开裂是牙根表面皮质骨缺失并延伸至牙槽嵴的缺损。","rationales":[{"en":"An isolated window with intact marginal bone is a fenestration.","zh":"边缘骨完整的孤立窗口状缺损是骨开窗。"},{"en":"Correct: dehiscence includes loss of the marginal alveolar bone.","zh":"正确：骨开裂包括牙槽边缘骨的缺失。"},{"en":"A through-and-through defect refers to advanced furcation involvement.","zh":"完全贯通缺损指进展性分叉受累。"},{"en":"A suprabony pocket is a soft-tissue relationship to bone, not a cortical defect.","zh":"骨上袋描述软组织与骨的关系，不是皮质骨缺损。"}],"level":"Board-style","pearl":"Dehiscence is a denuded root area where cortical bone loss extends to and includes the alveolar crest."},{"id":33,"concept":"Occlusion","stem":"Trauma from occlusion alone:","choices":["Initiates plaque-induced gingivitis","Does not initiate periodontitis but may modify tissue response and mobility","Always causes angular bone loss without plaque","Eliminates periodontal pockets"],"answer":1,"why":"Occlusal trauma does not initiate plaque-induced periodontal inflammation, but it may increase mobility and alter supporting tissues when inflammation is present.","zh":"咬合创伤不会启动菌斑性牙周炎症，但在炎症存在时可增加松动并影响支持组织。","rationales":[{"en":"Plaque biofilm initiates gingivitis, not occlusal force alone.","zh":"牙龈炎由菌斑生物膜启动，不是单纯咬合力。"},{"en":"Correct: it is a modifying factor rather than the primary inflammatory cause.","zh":"正确：它是修饰因素，而非主要炎症病因。"},{"en":"Bone loss is not inevitable in the absence of inflammation.","zh":"没有炎症时并不必然发生骨丧失。"},{"en":"Occlusal trauma does not eliminate pockets.","zh":"咬合创伤不会消除牙周袋。"}],"level":"Clinical","pearl":"Occlusal trauma does not initiate plaque-induced periodontal inflammation, but it may increase mobility and alter supporting tissues when inflammation is present."},{"id":34,"concept":"Implants","stem":"Peri-implant mucositis is characterized by:","choices":["Inflammation with bleeding around an implant without supporting bone loss beyond initial remodelling","Progressive bone loss with implant mobility in every case","Pulpal necrosis of the implant","Dental caries on the implant surface"],"answer":0,"why":"Peri-implant mucositis is a reversible inflammatory lesion confined to the soft tissues around an implant.","zh":"种植体周黏膜炎是局限于种植体周软组织的可逆性炎症，不伴超出初始改建的骨丧失。","rationales":[{"en":"Correct: soft-tissue inflammation without progressive supporting bone loss defines mucositis.","zh":"正确：软组织炎症且无进行性支持骨丧失定义黏膜炎。"},{"en":"Progressive bone loss indicates peri-implantitis, while mobility may indicate failure.","zh":"进行性骨丧失提示种植体周炎，松动可提示失败。"},{"en":"Implants have no dental pulp.","zh":"种植体没有牙髓。"},{"en":"Titanium implant surfaces do not develop dental caries.","zh":"钛种植体表面不会发生龋病。"}],"level":"Board-style","pearl":"Peri-implant mucositis is a reversible inflammatory lesion confined to the soft tissues around an implant."},{"id":35,"concept":"Implants","stem":"Peri-implantitis differs from peri-implant mucositis by the presence of:","choices":["Progressive supporting bone loss","Plaque only","Bleeding only","A prosthetic crown"],"answer":0,"why":"Peri-implantitis includes inflammation plus progressive loss of supporting bone around the implant.","zh":"种植体周炎包括炎症以及种植体周支持骨进行性丧失。","rationales":[{"en":"Correct: progressive bone loss is the key distinguishing feature.","zh":"正确：进行性骨丧失是关键区别。"},{"en":"Plaque may be present in both conditions and does not distinguish them.","zh":"两种情况都可有菌斑，不能用于区分。"},{"en":"Bleeding may occur in both mucositis and peri-implantitis.","zh":"黏膜炎和种植体周炎都可能出血。"},{"en":"A prosthetic crown is a normal component and is not diagnostic.","zh":"修复冠是正常组成部分，不具诊断意义。"}],"level":"Board-style","pearl":"Peri-implantitis includes inflammation plus progressive loss of supporting bone around the implant."},{"id":36,"concept":"Systemic Links","stem":"The most accurate statement about periodontal disease and systemic health is:","choices":["They are completely unrelated","Periodontal inflammation shares risk factors and biologic pathways with several systemic conditions, but association does not automatically prove causation","Periodontitis directly causes every cardiovascular event","Scaling cures diabetes"],"answer":1,"why":"Periodontitis is associated with conditions such as diabetes and cardiovascular disease through shared inflammatory and risk pathways, but causal claims require caution.","zh":"牙周炎与糖尿病和心血管病等存在共享炎症及危险通路的关联，但不能轻率认定因果。","rationales":[{"en":"Evidence supports meaningful associations, so complete lack of relationship is inaccurate.","zh":"已有证据支持重要关联，因此说完全无关不准确。"},{"en":"Correct: association and biologic plausibility are recognized while causation must be interpreted carefully.","zh":"正确：应承认关联和生物学合理性，同时谨慎解释因果。"},{"en":"Periodontitis is not proven to directly cause every cardiovascular event.","zh":"牙周炎并未被证明直接导致所有心血管事件。"},{"en":"Periodontal therapy may support metabolic control but does not cure diabetes.","zh":"牙周治疗可辅助代谢控制，但不能治愈糖尿病。"}],"level":"Clinical","pearl":"Periodontitis is associated with conditions such as diabetes and cardiovascular disease through shared inflammatory and risk pathways, but causal claims require caution."},{"id":37,"concept":"Prognosis","stem":"Which factor generally worsens the prognosis of an individual tooth?","choices":["Favourable crown-to-root ratio and no mobility","Advanced furcation involvement and severe attachment loss","Excellent plaque control","Stable shallow probing depths"],"answer":1,"why":"Advanced furcation involvement and severe attachment loss reduce periodontal support and complicate instrumentation and maintenance.","zh":"进展性分叉受累和严重附着丧失会减少牙周支持，并增加清创和维护难度。","rationales":[{"en":"A favourable crown-to-root ratio and stability improve prognosis.","zh":"良好的冠根比和稳定性会改善预后。"},{"en":"Correct: loss of support and inaccessible furcations worsen prognosis.","zh":"正确：支持组织丧失及难以清洁的分叉会恶化预后。"},{"en":"Excellent plaque control improves treatment response and prognosis.","zh":"良好菌斑控制可改善治疗反应和预后。"},{"en":"Stable shallow pockets are favourable, not adverse.","zh":"稳定的浅袋属于有利因素，而非不良因素。"}],"level":"Board-style","pearl":"Advanced furcation involvement and severe attachment loss reduce periodontal support and complicate instrumentation and maintenance."},{"id":38,"concept":"Clinical Priorities","stem":"A patient presents with generalized 7–8 mm bleeding pockets and heavy subgingival calculus. What is the BEST initial treatment approach?","choices":["Immediate extraction of all teeth","Comprehensive assessment, risk control, oral hygiene instruction, and staged nonsurgical debridement","Wait until pain develops","Provide polishing only"],"answer":1,"why":"Initial periodontal therapy addresses diagnosis, modifiable risks, daily biofilm control, and thorough nonsurgical debridement before reevaluation.","zh":"初期牙周治疗应完成诊断、控制可改变风险、指导日常菌斑控制并分阶段彻底非手术清创，随后再评估。","rationales":[{"en":"Extraction is not justified before assessing restorability and response to therapy.","zh":"在评估可保留性和治疗反应前不应全部拔牙。"},{"en":"Correct: cause-related nonsurgical therapy is the appropriate first phase.","zh":"正确：病因导向的非手术治疗是适当的第一阶段。"},{"en":"Periodontal destruction may progress without pain, so waiting is unsafe.","zh":"牙周破坏可在无痛时进展，等待出现疼痛不安全。"},{"en":"Polishing removes superficial stain but does not treat deep biofilm or calculus.","zh":"抛光只能去除表面色素，不能治疗深部菌斑和牙石。"}],"level":"Board-style","pearl":"Initial periodontal therapy addresses diagnosis, modifiable risks, daily biofilm control, and thorough nonsurgical debridement before reevaluation."},{"id":39,"concept":"Clinical Priorities","stem":"Which site should receive the greatest priority during periodontal reassessment?","choices":["A 3 mm site with no bleeding","An 8 mm site with bleeding and suppuration","A healthy implant with no inflammation","A stable torus"],"answer":1,"why":"A deep site with bleeding and suppuration indicates ongoing active inflammation and requires prompt evaluation and treatment planning.","zh":"8毫米深袋伴出血和溢脓提示持续活动性炎症，应优先评估和制定治疗计划。","rationales":[{"en":"A shallow nonbleeding site is stable and lower priority.","zh":"浅且不出血的部位较稳定，优先级较低。"},{"en":"Correct: depth, bleeding, and suppuration together signal active high-risk disease.","zh":"正确：深度、出血和溢脓共同提示高风险活动性病变。"},{"en":"A healthy implant without inflammation does not require urgent intervention.","zh":"无炎症的健康种植体不需紧急处理。"},{"en":"A stable torus is a benign anatomic finding.","zh":"稳定骨隆突是良性解剖表现。"}],"level":"Clinical","pearl":"A deep site with bleeding and suppuration indicates ongoing active inflammation and requires prompt evaluation and treatment planning."},{"id":40,"concept":"Patient Education","stem":"The MOST effective self-care recommendation for an open interdental space with exposed root surfaces is often:","choices":["An appropriately sized interdental brush","Floss held loosely without contacting either tooth","A hard-bristle brush used forcefully","No interdental cleaning"],"answer":0,"why":"An appropriately sized interdental brush efficiently disrupts plaque in open embrasures and around exposed root concavities.","zh":"合适尺寸的牙间刷能有效清除开放性邻间隙及暴露根面凹陷处菌斑。","rationales":[{"en":"Correct: interdental brushes are effective where embrasures are open.","zh":"正确：开放性邻间隙适合使用牙间刷。"},{"en":"Loose floss that does not adapt to tooth surfaces will not remove plaque effectively.","zh":"不贴合牙面的松弛牙线无法有效清除菌斑。"},{"en":"Forceful hard-bristle brushing increases abrasion and recession risk.","zh":"用硬毛刷强力刷牙会增加磨损和退缩风险。"},{"en":"Open spaces require daily interdental cleaning rather than omission.","zh":"开放性间隙需要每日邻间清洁，而不是不清洁。"}],"level":"Board-style","pearl":"An appropriately sized interdental brush efficiently disrupts plaque in open embrasures and around exposed root concavities."},{"id":41,"concept":"Patient Education","stem":"For a patient who smokes and has periodontitis, the BEST counselling message is:","choices":["Smoking has no effect once calculus is removed","Smoking cessation is an important part of periodontal treatment because it improves healing and lowers progression risk","Switching cigarette brands eliminates periodontal risk","Brushing harder offsets smoking risk"],"answer":1,"why":"Smoking cessation should be integrated into periodontal care because tobacco worsens disease and reduces healing response.","zh":"戒烟应纳入牙周治疗，因为烟草会加重疾病并降低愈合反应。","rationales":[{"en":"Calculus removal does not eliminate the host and healing effects of smoking.","zh":"去除牙石不能消除吸烟对宿主反应和愈合的影响。"},{"en":"Correct: cessation meaningfully improves periodontal prognosis and treatment response.","zh":"正确：戒烟可显著改善牙周预后和治疗反应。"},{"en":"Changing brands does not remove tobacco-related risk.","zh":"更换香烟品牌不能消除烟草风险。"},{"en":"More forceful brushing cannot counter systemic smoking effects and may injure tissues.","zh":"更用力刷牙不能抵消吸烟的全身影响，反而可能损伤组织。"}],"level":"Board-style","pearl":"Smoking cessation should be integrated into periodontal care because tobacco worsens disease and reduces healing response."},{"id":42,"concept":"Staging & Grading","stem":"A patient has interdental clinical attachment loss of 5 mm at the site of greatest loss, radiographic bone loss extending to the middle third of the root, and no tooth loss due to periodontitis. Which stage is MOST appropriate?","choices":["Stage I","Stage II","Stage III","Stage IV"],"answer":2,"why":"Interdental CAL of 5 mm or more and bone loss to the middle third of the root meet Stage III severity criteria when Stage IV complexity is absent.","zh":"牙间临床附着丧失达到5毫米或以上，且骨丧失延伸至根中三分之一，在无IV期复杂因素时符合III期严重程度标准。","rationales":[{"en":"Stage I is limited to 1–2 mm interdental CAL and coronal-third bone loss under 15%.","zh":"I期通常仅有1–2毫米牙间附着丧失，骨丧失位于冠方三分之一且低于15%。"},{"en":"Stage II generally involves 3–4 mm interdental CAL and coronal-third bone loss of 15%–33%.","zh":"II期通常为3–4毫米牙间附着丧失，冠方三分之一骨丧失约15%–33%。"},{"en":"Correct: CAL of at least 5 mm with bone loss reaching the middle third supports Stage III.","zh":"正确：附着丧失至少5毫米且骨丧失达到根中三分之一支持III期。"},{"en":"Stage IV requires Stage III severity plus major complexity such as masticatory dysfunction, severe ridge defects, or extensive tooth loss.","zh":"IV期除III期严重程度外，还需咀嚼功能障碍、严重牙槽嵴缺损或广泛失牙等复杂因素。"}],"level":"Clinical","pearl":"Stage is based on severity and complexity; CAL of 5 mm or more commonly places a case in Stage III or IV."},{"id":43,"concept":"Staging & Grading","stem":"A 40-year-old has 40% radiographic bone loss at the worst site. The bone-loss-to-age ratio is approximately 1.0. Which grade is MOST consistent with this finding?","choices":["Grade A","Grade B","Grade C","The grade cannot be estimated"],"answer":2,"why":"A bone-loss-to-age ratio greater than 1.0 indicates rapid progression and supports Grade C.","zh":"骨丧失百分比与年龄之比大于1.0提示快速进展，支持C级。","rationales":[{"en":"Grade A is associated with a ratio below 0.25 and little evidence of progression.","zh":"A级通常对应比值低于0.25，并且几乎无进展证据。"},{"en":"Grade B usually corresponds to a ratio from 0.25 to 1.0; a value at the upper boundary requires clinical judgment, but values above 1.0 indicate Grade C.","zh":"B级通常对应0.25至1.0；处于上限时需结合临床判断，而超过1.0提示C级。"},{"en":"Correct: approximately 40% bone loss at age 40 gives a ratio near 1.0; if clearly at or above the rapid-progression threshold, Grade C is most appropriate.","zh":"正确：40岁时约40%骨丧失，比值接近1.0；若达到或超过快速进展阈值，最符合C级。"},{"en":"A grade can be estimated from indirect evidence when previous longitudinal records are unavailable.","zh":"即使缺乏纵向记录，也可利用间接证据估计分级。"}],"level":"Clinical","pearl":"Bone-loss percentage divided by age is an indirect grading tool: less than 0.25 suggests A, 0.25–1.0 suggests B, and greater than 1.0 suggests C."},{"id":44,"concept":"Assessment","stem":"A site has a 5 mm probing depth and the gingival margin is 3 mm coronal to the CEJ because of enlargement. What is the clinical attachment level?","choices":["2 mm","5 mm","8 mm","3 mm"],"answer":0,"why":"When the gingival margin is coronal to the CEJ, CAL equals probing depth minus the amount of enlargement: 5 − 3 = 2 mm.","zh":"当龈缘位于釉牙骨质界冠方时，临床附着水平等于探诊深度减去增生量：5−3=2毫米。","rationales":[{"en":"Correct: 5 mm probing depth minus 3 mm gingival enlargement equals 2 mm CAL.","zh":"正确：5毫米探诊深度减去3毫米牙龈增生等于2毫米附着丧失。"},{"en":"Five millimetres is the probing depth and does not account for the coronal position of the gingival margin.","zh":"5毫米只是探诊深度，未考虑龈缘位于釉牙骨质界冠方。"},{"en":"Eight millimetres would result from adding enlargement, which is used only when the margin is apical because of recession.","zh":"8毫米来自错误相加；只有龈缘因退缩位于根方时才应相加。"},{"en":"Three millimetres is the amount of enlargement, not the attachment level.","zh":"3毫米是增生量，不是临床附着水平。"}],"level":"Clinical","pearl":"CAL equals probing depth plus recession, but probing depth minus enlargement when the gingival margin is coronal to the CEJ."},{"id":45,"concept":"Furcations","stem":"A Nabers probe passes completely through a mandibular molar furcation, but the furcation is not clinically visible because it is covered by soft tissue. How is this classified?","choices":["Class I","Class II","Class III","Class IV"],"answer":2,"why":"A through-and-through furcation covered by soft tissue is Class III.","zh":"完全贯通但被软组织覆盖的分叉病变属于III度。","rationales":[{"en":"Class I is incipient involvement with minimal horizontal penetration.","zh":"I度为初期受累，仅有轻微水平进入。"},{"en":"Class II is a partial cul-de-sac defect that is not through-and-through.","zh":"II度为部分盲袋状缺损，尚未贯通。"},{"en":"Correct: Class III is through-and-through but remains covered by soft tissue.","zh":"正确：III度完全贯通，但仍被软组织覆盖。"},{"en":"Class IV is through-and-through and clinically visible because of recession.","zh":"IV度为完全贯通，并因退缩而临床可见。"}],"level":"Board-style","pearl":"Class III is through-and-through but covered; Class IV is through-and-through and clinically visible."},{"id":46,"concept":"Mobility & Occlusion","stem":"Which finding is MOST characteristic of primary occlusal trauma?","choices":["Occlusal forces acting on a tooth with normal periodontal support","Normal forces acting on a tooth with reduced periodontal support","Plaque-induced attachment loss without excessive force","Generalized gingival inflammation without mobility"],"answer":0,"why":"Primary occlusal trauma occurs when excessive occlusal forces act on a tooth with otherwise normal periodontal support.","zh":"原发性咬合创伤是指过大咬合力作用于牙周支持正常的牙齿。","rationales":[{"en":"Correct: excessive force on normal support defines primary occlusal trauma.","zh":"正确：过大力量作用于正常支持组织定义原发性咬合创伤。"},{"en":"Normal or excessive forces acting on reduced support describe secondary occlusal trauma.","zh":"正常或过大力量作用于已减少的支持组织属于继发性咬合创伤。"},{"en":"Plaque-induced attachment loss is inflammatory periodontitis, not occlusal trauma by itself.","zh":"菌斑诱导的附着丧失属于炎症性牙周炎，本身并非咬合创伤。"},{"en":"Gingival inflammation alone does not establish occlusal trauma.","zh":"仅有牙龈炎症不能诊断咬合创伤。"}],"level":"Board-style","pearl":"Primary trauma involves excessive force on normal support; secondary trauma occurs when support is already reduced."},{"id":47,"concept":"Radiographic Interpretation","stem":"Which radiographic pattern BEST describes horizontal bone loss?","choices":["The alveolar crest remains roughly parallel to a line connecting adjacent CEJs but is positioned more apically","An angular defect creates a sloping bone level that is not parallel to adjacent CEJs","A widened periodontal ligament space only","A radiopaque mass attached to the root"],"answer":0,"why":"Horizontal bone loss produces an apically displaced crest that remains approximately parallel to the CEJ line.","zh":"水平型骨丧失使牙槽嵴向根方移位，但仍大致平行于相邻牙釉牙骨质界连线。","rationales":[{"en":"Correct: the crest is lowered but remains approximately parallel to adjacent CEJs.","zh":"正确：牙槽嵴降低，但仍大致平行于相邻釉牙骨质界。"},{"en":"A sloping or angular defect describes vertical bone loss.","zh":"倾斜或角形缺损描述的是垂直型骨丧失。"},{"en":"A widened PDL space may suggest occlusal stress but does not define horizontal bone loss.","zh":"牙周膜间隙增宽可提示咬合应力，但不定义水平型骨丧失。"},{"en":"A radiopaque root-associated mass suggests calculus or another calcified finding, not the bone-loss pattern.","zh":"附着于根面的不透射影可提示牙石或其他钙化物，并非骨丧失类型。"}],"level":"Clinical","pearl":"Horizontal loss stays roughly parallel to the CEJ line; vertical loss creates an angular defect."},{"id":48,"concept":"Radiographic Interpretation","stem":"A 30-year-old has radiographic bone loss extending 30% down the root. Which statement is MOST accurate?","choices":["The bone-loss-to-age ratio is about 0.1","The ratio is about 0.5","The ratio is about 1.0","The ratio is about 3.0"],"answer":2,"why":"The indirect progression ratio is percent bone loss divided by age: 30 ÷ 30 = 1.0.","zh":"间接进展比值为骨丧失百分比除以年龄：30÷30=1.0。","rationales":[{"en":"A ratio of 0.1 would correspond to only about 3% bone loss at age 30.","zh":"0.1的比值在30岁时仅相当于约3%骨丧失。"},{"en":"A ratio of 0.5 would correspond to about 15% bone loss at age 30.","zh":"0.5的比值在30岁时约相当于15%骨丧失。"},{"en":"Correct: 30% divided by age 30 equals 1.0.","zh":"正确：30%除以30岁等于1.0。"},{"en":"A ratio of 3.0 would require about 90% bone loss at age 30.","zh":"3.0的比值在30岁时需约90%骨丧失。"}],"level":"Calculation","pearl":"For indirect grading, divide the greatest percentage of radiographic bone loss by the patient's age."},{"id":49,"concept":"Risk Factors","stem":"A patient with poorly controlled diabetes and periodontitis is MOST likely to experience which effect?","choices":["Reduced periodontal inflammation and faster healing","Greater disease severity and a less predictable healing response","Complete protection from attachment loss","No influence on periodontal risk"],"answer":1,"why":"Poor glycemic control increases inflammatory burden, periodontal destruction risk, and the likelihood of delayed or less predictable healing.","zh":"血糖控制不佳会增加炎症负担、牙周破坏风险，并使愈合延迟或更难预测。","rationales":[{"en":"Poor glycemic control tends to worsen inflammation and healing rather than improve them.","zh":"血糖控制不佳通常会加重炎症并影响愈合，而不是改善。"},{"en":"Correct: uncontrolled diabetes is an important modifier of periodontitis severity and treatment response.","zh":"正确：未控制糖尿病是影响牙周炎严重程度和治疗反应的重要因素。"},{"en":"Diabetes does not protect against attachment loss.","zh":"糖尿病不会保护患者免受附着丧失。"},{"en":"The relationship is clinically significant and should influence risk assessment and care planning.","zh":"这种关系具有临床意义，应影响风险评估和治疗计划。"}],"level":"Clinical","pearl":"Poor glycemic control increases periodontitis risk and can impair healing; periodontal inflammation may also complicate metabolic control."},{"id":50,"concept":"Risk Factors","stem":"Why can bleeding on probing underestimate periodontal inflammation in a patient who smokes heavily?","choices":["Smoking increases gingival blood flow","Nicotine-related vasoconstriction may suppress visible bleeding","Smoking eliminates subgingival biofilm","Smokers cannot develop deep pockets"],"answer":1,"why":"Nicotine-related vasoconstriction can reduce overt bleeding even when substantial inflammation and destruction are present.","zh":"尼古丁相关血管收缩可减少明显出血，即使存在显著炎症和组织破坏。","rationales":[{"en":"Smoking generally reduces, rather than increases, gingival blood flow through vasoconstrictive effects.","zh":"吸烟通过血管收缩通常减少而不是增加牙龈血流。"},{"en":"Correct: suppressed bleeding can mask disease severity in smokers.","zh":"正确：出血受抑制可能掩盖吸烟者的疾病严重程度。"},{"en":"Smoking does not eliminate subgingival biofilm.","zh":"吸烟不会消除龈下菌斑。"},{"en":"Smokers can develop deep pockets and advanced attachment loss.","zh":"吸烟者仍可形成深牙周袋和严重附着丧失。"}],"level":"Board-style","pearl":"Reduced bleeding in a smoker does not necessarily indicate health."},{"id":51,"concept":"Instrumentation","stem":"Which instrument is BEST suited for removing moderate to heavy subgingival calculus from the mesial surface of a posterior tooth?","choices":["Gracey 11/12 curet","Gracey 13/14 curet","Sickle scaler used deep subgingivally","Universal curet restricted to supragingival use"],"answer":0,"why":"The Gracey 11/12 is area-specific for mesial surfaces of posterior teeth.","zh":"Gracey 11/12为后牙近中面专用的区域特异性刮治器。","rationales":[{"en":"Correct: the Gracey 11/12 is designed for mesial posterior surfaces.","zh":"正确：Gracey 11/12专用于后牙近中面。"},{"en":"The Gracey 13/14 is designed primarily for distal posterior surfaces.","zh":"Gracey 13/14主要用于后牙远中面。"},{"en":"A sickle scaler has a pointed tip and triangular cross-section, making it unsuitable for deep subgingival adaptation.","zh":"镰形洁治器尖端锐利、横截面呈三角形，不适合深部龈下贴合。"},{"en":"A universal curet can be used subgingivally and is not restricted to supragingival instrumentation.","zh":"通用刮治器可用于龈下，并非仅限龈上。"}],"level":"Clinical","pearl":"Gracey 11/12 is for posterior mesial surfaces; Gracey 13/14 is for posterior distal surfaces."},{"id":52,"concept":"Instrumentation","stem":"During ultrasonic instrumentation on a patient with a modern cardiac pacemaker, what is the BEST approach?","choices":["Assume every ultrasonic device is absolutely contraindicated","Review the device history and manufacturer guidance, then use appropriate precautions or alternatives","Place the ultrasonic unit directly over the pacemaker","Ignore the pacemaker because dental equipment never interferes"],"answer":1,"why":"Modern devices vary; the clinician should verify pacemaker type, follow manufacturer and medical guidance, and select magnetostrictive, piezoelectric, or hand instrumentation appropriately.","zh":"现代心脏装置各不相同；临床人员应确认起搏器类型，遵循制造商和医疗建议，并适当选择超声或手用器械。","rationales":[{"en":"A blanket prohibition is outdated because compatibility varies by device and equipment.","zh":"一概禁用已不合时宜，因为不同装置和设备的兼容性不同。"},{"en":"Correct: individualized verification and risk-based precautions are safest.","zh":"正确：个体化确认并采取基于风险的预防措施最安全。"},{"en":"Placing equipment over the pacemaker could increase interference risk and is inappropriate.","zh":"将设备直接置于起搏器上方可能增加干扰风险，不合适。"},{"en":"Electromagnetic interference is possible with some combinations, so the history cannot be ignored.","zh":"某些组合可能发生电磁干扰，因此不能忽视病史。"}],"level":"Clinical","pearl":"Do not use a blanket rule; verify the cardiac device and follow current manufacturer and medical guidance."},{"id":53,"concept":"Nonsurgical Therapy","stem":"After completing scaling and root debridement, when is periodontal reevaluation commonly scheduled to allow tissue healing and assessment of response?","choices":["The same day","About 4–6 weeks later","Exactly 12 months later","Only if the patient reports pain"],"answer":1,"why":"A reevaluation after approximately 4–6 weeks commonly allows inflammation to resolve and tissues to heal enough for meaningful reassessment.","zh":"约4–6周后复评通常可让炎症消退并使组织充分愈合，从而进行有意义的再评估。","rationales":[{"en":"Same-day measurements cannot show the healing response to completed therapy.","zh":"当天测量无法显示完成治疗后的愈合反应。"},{"en":"Correct: 4–6 weeks is a common interval for reassessing probing, bleeding, plaque control, and residual disease.","zh":"正确：4–6周是复查探诊、出血、菌斑控制和残余病变的常见时间。"},{"en":"Waiting a full year would delay needed retreatment or referral.","zh":"等待整整一年会延误必要的再治疗或转诊。"},{"en":"Periodontal disease may remain active without pain, so reevaluation should be planned routinely.","zh":"牙周病可在无痛时仍活动，因此应常规安排复评。"}],"level":"Clinical","pearl":"Reevaluate after healing, commonly around 4–6 weeks, rather than relying on symptoms."},{"id":54,"concept":"Reevaluation","stem":"At reevaluation, a previously 7 mm pocket is now 6 mm with persistent bleeding and residual calculus. What is the BEST next step?","choices":["Declare treatment complete because the depth improved by 1 mm","Reinstrument the site, reassess contributing factors, and consider periodontal referral if it remains nonresponsive","Polish only","Extend maintenance to 12 months"],"answer":1,"why":"Persistent deep bleeding sites with residual deposits require further cause-related therapy and possibly specialist evaluation.","zh":"持续深袋伴出血和残余沉积物需要进一步病因治疗，并可能需要牙周专科评估。","rationales":[{"en":"A small improvement does not make a 6 mm bleeding site stable or healthy.","zh":"仅改善1毫米并不能使6毫米出血部位变得稳定或健康。"},{"en":"Correct: remove residual deposits, reassess risk and technique, and refer when response remains inadequate.","zh":"正确：去除残余沉积物，重新评估风险和技术，若反应仍不佳则转诊。"},{"en":"Polishing does not treat residual subgingival calculus or deep inflammation.","zh":"抛光不能处理残余龈下牙石或深部炎症。"},{"en":"A 12-month interval is inappropriate for an active high-risk site.","zh":"活动性高风险部位不适合12个月维护间隔。"}],"level":"Clinical","pearl":"Residual deep bleeding pockets require active management, not passive maintenance."},{"id":55,"concept":"Maintenance","stem":"Which patient most clearly requires a short periodontal maintenance interval, such as every 3 months?","choices":["A healthy patient with excellent plaque control and no attachment loss","A smoker with previous Stage III periodontitis, residual 5–6 mm bleeding pockets, and inconsistent home care","A patient with a stable torus","A child with no gingival inflammation"],"answer":1,"why":"Past severe disease, smoking, residual pockets, bleeding, and poor self-care combine to create high recurrence risk and justify close maintenance.","zh":"既往严重牙周病、吸烟、残余深袋、出血及自我护理不佳共同造成高复发风险，需较短维护间隔。","rationales":[{"en":"A healthy low-risk patient may be managed at a longer individualized interval.","zh":"健康低风险患者可采用更长的个体化间隔。"},{"en":"Correct: multiple high-risk factors support approximately 3-month periodontal maintenance.","zh":"正确：多项高风险因素支持约3个月一次的牙周维护。"},{"en":"A stable torus does not determine periodontal maintenance frequency.","zh":"稳定骨隆突不决定牙周维护频率。"},{"en":"A child without inflammation is not a periodontal-maintenance case.","zh":"无炎症儿童并非牙周维护病例。"}],"level":"Clinical","pearl":"Maintenance intervals are risk-based; previous severe disease and residual inflammation often require 3-month care."},{"id":56,"concept":"Implants","stem":"Which combination MOST strongly suggests peri-implantitis rather than peri-implant mucositis?","choices":["Bleeding on probing without bone loss","Suppuration, increased probing depth, and progressive crestal bone loss","A stable implant with no bleeding","Plaque on the crown without tissue inflammation"],"answer":1,"why":"Peri-implantitis involves inflammatory signs together with progressive supporting bone loss.","zh":"种植体周炎包括炎症征象以及进行性支持骨丧失。","rationales":[{"en":"Bleeding without progressive bone loss is more consistent with peri-implant mucositis.","zh":"出血但无进行性骨丧失更符合种植体周黏膜炎。"},{"en":"Correct: suppuration, deeper probing, and progressive bone loss indicate peri-implantitis.","zh":"正确：溢脓、探诊加深及进行性骨丧失提示种植体周炎。"},{"en":"A stable nonbleeding implant is consistent with peri-implant health.","zh":"稳定且不出血的种植体符合种植体周健康。"},{"en":"Plaque alone does not establish peri-implant disease without inflammatory tissue changes.","zh":"仅有菌斑而无组织炎症变化不能诊断种植体周疾病。"}],"level":"Clinical","pearl":"Progressive bone loss is the defining distinction between peri-implantitis and mucositis."},{"id":57,"concept":"Implants","stem":"Which instrument choice is MOST appropriate for routine biofilm and light calculus removal around a titanium implant?","choices":["A coarse stainless-steel curet used aggressively","An implant-compatible instrument or appropriately selected low-abrasive ultrasonic tip","A high-speed bur on the implant surface","No instrumentation because implants cannot develop inflammation"],"answer":1,"why":"Implant-compatible instruments and low-abrasive tips help remove deposits while minimizing unnecessary surface damage.","zh":"种植体兼容器械和低磨损工作尖可去除沉积物，同时尽量减少表面损伤。","rationales":[{"en":"Aggressive coarse stainless-steel instrumentation may unnecessarily scratch or alter the implant surface.","zh":"粗糙不锈钢器械的强力操作可能不必要地划伤或改变种植体表面。"},{"en":"Correct: use instrumentation designed or selected for implant surface safety.","zh":"正确：应使用专为种植体表面安全设计或选择的器械。"},{"en":"A high-speed bur is not appropriate for routine implant maintenance.","zh":"高速车针不适用于常规种植体维护。"},{"en":"Implants can develop mucositis and peri-implantitis and require professional maintenance.","zh":"种植体可发生黏膜炎和种植体周炎，需要专业维护。"}],"level":"Clinical","pearl":"Choose implant-safe instruments that remove deposits without unnecessary surface damage."},{"id":58,"concept":"Prognosis","stem":"Which combination gives the POOREST prognosis for a mandibular molar?","choices":["Shallow pockets, no mobility, and favourable root form","Class III furcation involvement, severe attachment loss, mobility, and poor plaque control","Localized gingivitis with intact bone","A stable restoration and excellent maintenance attendance"],"answer":1,"why":"Advanced furcation involvement, reduced support, mobility, and poor plaque control together markedly reduce long-term maintainability.","zh":"严重分叉受累、支持组织减少、牙齿松动和菌斑控制不佳共同显著降低长期可维护性。","rationales":[{"en":"Shallow pockets and stable support indicate a favourable prognosis.","zh":"浅袋和稳定支持组织提示良好预后。"},{"en":"Correct: multiple severe local and behavioural risk factors produce the poorest prognosis.","zh":"正确：多项严重局部和行为风险因素造成最差预后。"},{"en":"Gingivitis without bone loss is reversible and usually has a good prognosis.","zh":"无骨丧失的牙龈炎可逆，通常预后良好。"},{"en":"Stable restoration and excellent maintenance improve prognosis.","zh":"稳定修复体和良好维护可改善预后。"}],"level":"Board-style","pearl":"Tooth prognosis integrates support, furcation, mobility, anatomy, inflammation, restorability, and patient-level risk."},{"id":59,"concept":"Systemic Links","stem":"What is the BEST evidence-based message for a patient with diabetes and periodontitis?","choices":["Periodontal treatment replaces diabetes management","Improved periodontal health may support glycemic control, but medical diabetes care must continue","Diabetes and periodontitis have no relationship","Antibiotics alone permanently eliminate both diseases"],"answer":1,"why":"Periodontal therapy may modestly support glycemic control, but it complements rather than replaces medical management of diabetes.","zh":"牙周治疗可能对血糖控制有一定帮助，但只能补充而不能替代糖尿病的医疗管理。","rationales":[{"en":"Dental treatment cannot replace medical monitoring, medication, nutrition, and other diabetes care.","zh":"牙科治疗不能替代血糖监测、药物、营养及其他糖尿病管理。"},{"en":"Correct: integrated periodontal and medical care recognizes the bidirectional association without overstating causation.","zh":"正确：综合牙周与医疗管理承认双向关联，同时不过度夸大因果。"},{"en":"The two conditions share important inflammatory and risk relationships.","zh":"这两种疾病存在重要的炎症及风险关联。"},{"en":"Antibiotics alone do not permanently eliminate chronic periodontitis or diabetes.","zh":"单用抗生素不能永久消除慢性牙周炎或糖尿病。"}],"level":"Clinical","pearl":"Periodontal care supports overall health but does not replace medical management."},{"id":60,"concept":"Clinical Priorities","stem":"A patient returns 6 weeks after nonsurgical periodontal therapy. Plaque control is excellent, bleeding has greatly decreased, but one molar retains a 7 mm vertical defect and Class II furcation. What is the BEST next step?","choices":["Continue routine polishing only","Discuss periodontal referral for further evaluation while maintaining excellent self-care","Stop all maintenance because inflammation improved","Extract the tooth immediately without assessing prognosis"],"answer":1,"why":"A persistent deep vertical defect with furcation involvement may require specialist evaluation even when overall inflammation and self-care have improved.","zh":"即使总体炎症和自我护理已改善，持续深垂直缺损伴分叉受累仍可能需要牙周专科评估。","rationales":[{"en":"Polishing alone will not address a persistent deep osseous and furcation defect.","zh":"单纯抛光不能处理持续的深部骨缺损和分叉病变。"},{"en":"Correct: specialist assessment can determine whether surgical, regenerative, or other therapy is appropriate.","zh":"正确：专科评估可判断是否适合手术、再生或其他治疗。"},{"en":"Maintenance remains necessary because periodontitis is a chronic, recurrence-prone condition.","zh":"牙周炎是慢性且易复发的疾病，因此仍需维护。"},{"en":"Immediate extraction is premature without evaluating restorability, prognosis, and treatment alternatives.","zh":"在评估可修复性、预后和替代方案前立即拔牙过于草率。"}],"level":"Clinical","pearl":"Persistent complex defects after good initial therapy warrant referral rather than neglect or automatic extraction."}];
window.FULL_BANK=PERIO_BANK;
